import Foundation

public enum CapturePolicy {
    public static let maximumTextBytes = 256 * 1024
    public static let maximumImageBytes = 10 * 1024 * 1024
    public static let maximumImageDimension = 16_384
    public static let maximumImagePixels = 32_000_000
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType"
    ]

    // A best-effort exclusion, not a guarantee that every secret can be identified.
    public static let passwordManagerBundleIDs: Set<String> = [
        "com.agilebits.onepassword7", "com.1password.1password",
        "com.bitwarden.desktop", "com.dashlane.Dashlane",
        "com.keepassxc.keepassxc", "com.apple.Passwords"
    ]

    public static func allows(types: Set<String>, sourceBundleIDs: [String]) -> Bool {
        types.isDisjoint(with: privateTypes)
            && sourceBundleIDs.allSatisfy { !passwordManagerBundleIDs.contains($0) }
    }

    public static func accepts(text: String) -> Bool {
        !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && text.utf8.count <= maximumTextBytes
    }

    public static func acceptsImage(width: Int, height: Int, byteCount: Int) -> Bool {
        width > 0 && height > 0 && width <= maximumImageDimension && height <= maximumImageDimension
            && width * height <= maximumImagePixels && byteCount > 0 && byteCount <= maximumImageBytes
    }
}
